func:
// Snapshot SIMULADO (sem CLP) — serve para testar o formato da evidência.
// Resultado marcado como source = "SIMULATED": NÃO vale como validação do CLP.
const v = {};
for (const t of flow.get("diag_tags") || []) {
    v[t.symbol] = t.type === "INT" || t.type === "WORD" ? 0 : false;
}
v.processo_segurancaOK = true; v.montagem_segurancaOK = true; v.expedicao_segurancaOK = true;
msg.payload = v;
msg.source = "SIMULATED";
return msg;

// Guarda o status de conexão mostrado pelo nó s7 in (online / offline / erro)
flow.set("diag_conn", (msg.status && msg.status.text) || "desconhecido");
flow.set("diag_conn_at", new Date().toISOString());
return null;

// GET /diag/s7  -> último snapshot em JSON
msg.payload = flow.get("last_diag") || { aviso: "Nenhum snapshot ainda. Clique em LER SNAPSHOT AGORA." };
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// GET /diag/s7.csv  -> último snapshot em CSV (abre no Excel). Salvar em docs/evidence/sprint1/
const s = flow.get("last_diag");
if (!s) { msg.statusCode = 404; msg.payload = "Nenhum snapshot ainda."; return msg; }
const q = (x) => '"' + String(x === null || x === undefined ? "" : x).replace(/"/g, '""') + '"';
const lines = [["captured_at", "source", "sinal", "simbolo", "endereco", "tipo", "valor_lido", "valor_tia", "confere"].join(";")];
for (const r of s.rows) {
    lines.push([s.captured_at, s.source, r.sinal, r.simbolo, r.endereco, r.tipo, r.valor_lido, "", ""].map(q).join(";"));
}
msg.payload = "\ufeff" + lines.join("\r\n");
msg.headers = {
    "Content-Type": "text/csv; charset=utf-8",
    "Content-Disposition": "attachment; filename=G1-leitura-s7-" + s.captured_at.replace(/[:.]/g, "-") + ".csv"
};
return msg;

// =============================================================================
// SIMULADOR DO CLP (desenvolvimento sem a bancada). Ativo só com INPUT_MODE=SIMULADOR.
// Gera um snapshot com OS MESMOS NOMES de variáveis do nó "s7 in" (modo "all").
// Botões: msg.topic = "sim_cmd", msg.payload = START | STOP | EMERGENCY | RESET
// =============================================================================
if ((env.get("INPUT_MODE") || "SIMULADOR") !== "SIMULADOR") { return null; }

let sim = context.get("sim") || { running: false, emergency: false, pulse: null, pulseTicks: 0, op: 1 };

if (msg.topic === "sim_cmd") {
    const cmd = String(msg.payload || "").toUpperCase();
    if (cmd === "START" && !sim.emergency) { sim.running = true; sim.pulse = "START"; }
    if (cmd === "STOP")      { sim.running = false; sim.pulse = "STOP"; }
    if (cmd === "EMERGENCY") { sim.running = false; sim.emergency = true; sim.pulse = null; }
    if (cmd === "RESET")     { sim.emergency = false; sim.pulse = null; }
    sim.pulseTicks = 3;                         // botão "fica apertado" ~300 ms
    context.set("sim", sim);
    node.status({ fill: "blue", shape: "ring", text: "SIM: " + cmd });
    return null;
}

const green = sim.pulseTicks > 0 && sim.pulse === "START";
const red   = sim.pulseTicks > 0 && sim.pulse === "STOP";
if (sim.pulseTicks > 0) { sim.pulseTicks--; }
context.set("sim", sim);

const belts = sim.running && !sim.emergency;
const station = (p) => ({
    [p + "_segurancaOK"]: !sim.emergency,
    [p + "_chaveAutomatico"]: true,
    [p + "_botaoVerde"]: green,
    [p + "_botaoVermelho"]: red,
    [p + "_esteira1"]: belts,
    [p + "_esteira2"]: belts
});

msg.payload = Object.assign(
    {
        emergencia: sim.emergency, emergenciaAtivada: sim.emergency,
        ocupado: belts, aguardando: !belts, manual: false,
        comutadorAutomatico: true, condicaoIniciar: !sim.emergency,
        numeroOP: sim.op, montagem_pecaStopper: belts, expedicao_pecaStopper: false
    },
    station("processo"), station("montagem"), station("expedicao")
);
msg.source = "SIMULATOR";
node.status({ fill: sim.emergency ? "red" : (belts ? "green" : "grey"), shape: "dot",
              text: sim.emergency ? "SIM: EMERGÊNCIA" : (belts ? "SIM: RODANDO" : "SIM: PARADO") });
return msg;

// =============================================================================
// REPLAY: recebe um snapshot capturado na bancada (POST /replay/s7) e injeta no
// pipeline como se viesse do nó "s7 in". Usado por tools/replay-telemetria.js.
// Corpo: { "captured_at": "ISO", "vars": { emergencia: false, ... } }
// Saída 1 -> pipeline · Saída 2 -> resposta HTTP
// =============================================================================
const mode = env.get("INPUT_MODE") || "SIMULADOR";
const body = msg.payload || {};
const res = { req: msg.req, res: msg.res, headers: { "Content-Type": "application/json" } };

if (mode !== "REPLAY") {
    return [null, Object.assign(res, { statusCode: 409,
        payload: { erro: "INPUT_MODE=" + mode + ". Mude a variável INPUT_MODE da aba para REPLAY e faça Deploy." } })];
}
if (!body.vars || typeof body.vars !== "object") {
    return [null, Object.assign(res, { statusCode: 400, payload: { erro: "Campo 'vars' ausente no corpo" } })];
}
const n = (context.get("count") || 0) + 1;
context.set("count", n);
node.status({ fill: "blue", shape: "dot", text: "replay: " + n + " leituras" });
return [
    { payload: body.vars, source: "REPLAY", captured_at: body.captured_at || null },
    Object.assign(res, { statusCode: 202, payload: { aceito: true, n: n } })
];

// =============================================================================
// FONTE ATIVA: deixa passar só a fonte escolhida em INPUT_MODE
//   CLP       -> leituras do nó "s7 in" (bancada real)
//   SIMULADOR -> simulador interno
//   REPLAY    -> capturas reinjetadas por tools/replay-telemetria.js
//   TESTE_B   -> payload sintético fixo do roteiro da Sprint 3 (substitui o s7 in)
// Saída 1 -> normalização · Saída 2 -> captura em arquivo (se CAPTURE=true)
// =============================================================================
const MAP = { CLP: "PLC", SIMULADOR: "SIMULATOR", REPLAY: "REPLAY", TESTE_B: "TESTE_B" };
const mode = env.get("INPUT_MODE") || "SIMULADOR";
global.set("input_mode_ingestao", mode);           // usado pela aba de comandos e pela ponte WSS
const source = msg.source || "PLC";               // o nó "s7 in" não marca a origem
if (MAP[mode] !== source) { return null; }
msg.source = source;

let capture = null;
if (env.get("CAPTURE") === "true" && source === "PLC") {
    // Uma linha JSON por leitura (formato lido pelo replay)
    capture = {
        filename: global.get("captureFile") || "captura-n2.jsonl",
        payload: JSON.stringify({ t: new Date().toISOString(), source: source, vars: msg.payload })
    };
}
return [msg, capture];

// =============================================================================
// NORMALIZAÇÃO: snapshot bruto do CLP -> amostra padronizada (uma a cada 100 ms)
// Mesma regra de machine_state da Sprint 1 (HIPÓTESE a validar na bancada,
// ver docs/mapeamento-clp.md e docs/tags/inventario_mapa_tags_n2.xlsx).
// Sprint 3: aceita também os nomes do Teste B do roteiro
//   { statusEstoqueOk, emergenciaEstoque, motorEsteira1, posEstoque }
// =============================================================================
const r = msg.payload || {};
const b = (k) => r[k] === true;
const NOMINAL = parseFloat(env.get("BELT_NOMINAL_SPEED"));

const st = (p) => ({
    // null = a variável não veio na leitura (ex.: Teste B); false = veio e está em falha
    seguranca_ok: typeof r[p + "_segurancaOK"] === "boolean" ? r[p + "_segurancaOK"] : null,
    automatico: b(p + "_chaveAutomatico"),
    botao_verde: b(p + "_botaoVerde"),
    botao_vermelho: b(p + "_botaoVermelho"),
    esteira1: b(p + "_esteira1"),
    esteira2: b(p + "_esteira2")
});
const stations = { processo: st("processo"), montagem: st("montagem"), expedicao: st("expedicao") };
const list = Object.values(stations);

const emergency   = b("emergencia") || b("emergenciaAtivada") || b("emergenciaEstoque");
const beltRunning = list.some(s => s.esteira1 || s.esteira2) || b("motorEsteira1");
const safetyFault = list.some(s => s.seguranca_ok === false) || r.statusEstoqueOk === false;

let state;
if (emergency)                        state = "EMERGENCY";
else if (safetyFault)                 state = "ALARM";
else if (beltRunning || b("ocupado")) state = "RUNNING";
else if (b("manual"))                 state = "PAUSED";
else                                  state = "STOPPED";

// Velocidade: só existe se o CLP tiver o registrador (ex. do enunciado: DB1.DBD4, a confirmar).
let beltSpeed = 0, speedSource = "PLC_DIGITAL";
if (typeof r.velocidadeEsteira === "number") { beltSpeed = r.velocidadeEsteira; speedSource = "PLC_ANALOG"; }
else if (beltRunning) {
    if (isNaN(NOMINAL)) { beltSpeed = null; speedSource = "UNAVAILABLE"; }
    else                { beltSpeed = NOMINAL; speedSource = "NOMINAL_CONFIG"; }
}

msg.payload = {
    t: Date.now(),
    source: msg.source,
    captured_at: msg.captured_at || null,
    machine_state: state,
    belt_running: beltRunning,
    belt_speed: beltSpeed,
    belt_speed_source: speedSource,
    buttons: {
        start_pressed: list.some(s => s.botao_verde),
        stop_pressed: list.some(s => s.botao_vermelho),
        emergency_pressed: emergency,
        reset_pressed: false              // sem endereço de Reset no mapa (pendência)
    },
    stations: stations,
    estoque: {
        seguranca_ok: typeof r.statusEstoqueOk === "boolean" ? r.statusEstoqueOk : null,
        posicao: typeof r.posEstoque === "number" ? r.posEstoque : null
    },
    flags: {
        ocupado: b("ocupado"), aguardando: b("aguardando"), manual: b("manual"),
        comutador_automatico: b("comutadorAutomatico"), condicao_iniciar: b("condicaoIniciar")
    },
    presence: { montagem: b("montagem_pecaStopper"), expedicao: b("expedicao_pecaStopper") },
    numero_op: typeof r.numeroOP === "number" ? r.numeroOP : null
};
return msg;

// =============================================================================
// AGREGADOR 500 ms: junta as amostras de 100 ms e emite UMA mensagem por janela.
// - Estado/valores: os da ÚLTIMA amostra da janela.
// - Botões: OU lógico na janela -> um toque de 100 ms nunca se perde.
// - aggregation: quantas amostras, % de tempo com esteira ligada, estados vistos.
// Entradas: amostra normalizada | msg.topic "__flush__" (inject a cada 500 ms)
// =============================================================================
const WINDOW_MS = Number(env.get("AGG_WINDOW_MS") || 500);
const MACHINE_ID = env.get("MACHINE_ID") || "SMART-40-PLANTA-N2";
let w = context.get("w");

if (msg.topic !== "__flush__") {
    const s = msg.payload;
    if (!w) {
        w = { start: s.t, n: 0, belt: 0, states: [], changes: 0, prevState: null,
              buttons: { start_pressed: false, stop_pressed: false, emergency_pressed: false, reset_pressed: false } };
    }
    w.n += 1;
    if (s.belt_running) w.belt += 1;
    if (w.states.indexOf(s.machine_state) < 0) w.states.push(s.machine_state);
    if (w.prevState !== null && w.prevState !== s.machine_state) w.changes += 1;
    w.prevState = s.machine_state;
    for (const k in w.buttons) { w.buttons[k] = w.buttons[k] || s.buttons[k] === true; }
    w.last = s;
    context.set("w", w);
    return null;
}

// ---- fim da janela ----
if (!w || w.n === 0) {
    node.status({ fill: "grey", shape: "ring", text: "sem leituras da fonte" });
    return null;
}
context.set("w", null);
const s = w.last;
const prevFinal = context.get("prevFinal");
// Emergência é estado travado (já aparece em machine_state); START/STOP são toques.
const changed = w.changes > 0 || (prevFinal !== undefined && prevFinal !== s.machine_state)
             || w.buttons.start_pressed || w.buttons.stop_pressed;
context.set("prevFinal", s.machine_state);

const seq = (context.get("seq") || 0) + 1;
context.set("seq", seq);
const now = Date.now();

msg.topic = env.get("MQTT_TOPIC_DATA") || "industria40/telemetry/data";
msg.payload = {
    schema_version: "1.1",                       // 1.1 = 1.0 + bloco "aggregation" (compatível)
    msg_id: MACHINE_ID + "-" + s.t + "-" + seq + "-" + Math.random().toString(36).slice(2, 8),
    machine_id: MACHINE_ID,
    timestamp: new Date(s.t).toISOString(),      // momento da última leitura da janela
    seq: seq,
    event: changed ? "STATE_CHANGE" : "PERIODIC",
    source: s.source,
    buffered: false,
    machine_state: s.machine_state,
    belt_running: s.belt_running,
    belt_speed: s.belt_speed,
    belt_speed_source: s.belt_speed_source,
    buttons: w.buttons,
    stations: s.stations,
    flags: s.flags,
    presence: s.presence,
    numero_op: s.numero_op,
    aggregation: {
        window_ms: WINDOW_MS,
        samples: w.n,
        window_start: new Date(w.start).toISOString(),
        window_end: new Date(s.t).toISOString(),
        belt_running_ratio: Math.round((w.belt / w.n) * 100) / 100,
        states_seen: w.states,
        state_changes: w.changes
    }
};
if (s.captured_at) msg.payload.replay = { captured_at: s.captured_at };

flow.set("last_telemetry", msg.payload);
// Últimas mensagens (GET /edge/recent) — usado pela validação de replay
const recent = flow.get("recent") || [];
recent.push(msg.payload);
if (recent.length > 3000) recent.splice(0, recent.length - 3000);
flow.set("recent", recent);
node.status({ fill: "green", shape: "dot", text: s.machine_state + " · " + w.n + " amostras · seq " + seq });
return msg;

// =============================================================================
// OUTBOX (SQLite) — grava TODA mensagem antes de qualquer envio (Outbox Pattern).
// O envio acontece no "Outbox: despacha"; a linha só vira SENT com o PUBACK do broker.
// =============================================================================
const db = global.get("outbox_db");
if (!db) { node.status({ fill: "red", shape: "ring", text: "outbox fechada" }); node.error("Outbox indisponível", msg); return null; }
const MAX = Number(env.get("OUTBOX_MAX") || 200000);
const p = msg.payload;
const online = flow.get("mqtt_online") === true && flow.get("force_offline") !== true;

db.prepare(`INSERT OR IGNORE INTO outbox_telemetry (msg_id, topic, payload, created_offline, created_at)
            VALUES (?, ?, ?, ?, ?)`)
  .run(p.msg_id, msg.topic, JSON.stringify(p), online ? 0 : 1, new Date().toISOString());

const pending = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
if (pending > MAX) {
    const excess = pending - MAX;
    db.prepare(`DELETE FROM outbox_telemetry WHERE id IN
                (SELECT id FROM outbox_telemetry WHERE status = 'PENDING' ORDER BY id LIMIT ?)`).run(excess);
    node.warn("Outbox cheia (" + MAX + "). Descartadas " + excess + " mensagens mais antigas.");
}
node.status({ fill: online ? "green" : "yellow", shape: "dot", text: "pendentes: " + Math.min(pending, MAX) });
return null;

initialize:
// Abre o SQLite da outbox e cria a tabela (mesmo DDL de db/002_outbox_telemetry.sql).
// Requer Node.js >= 22.13 (módulo nativo node:sqlite) e o bloco functionGlobalContext
// do node-red/settings.js.
const sqlite = global.get("sqlite");
if (!sqlite) {
    node.status({ fill: "red", shape: "ring", text: "SQLite indisponível (Node.js >= 22.13?)" });
    node.error("node:sqlite indisponível. Use Node.js 22.13+ e o settings.js do repositório.");
    return;
}
const file = global.get("outboxPath") || "outbox_n2.sqlite";
const db = new sqlite.DatabaseSync(file);
db.exec("PRAGMA journal_mode = WAL;");
db.exec(`CREATE TABLE IF NOT EXISTS outbox_telemetry (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    msg_id           TEXT    NOT NULL UNIQUE,
    topic            TEXT    NOT NULL,
    payload          TEXT    NOT NULL,
    status           TEXT    NOT NULL DEFAULT 'PENDING'
                     CHECK (status IN ('PENDING', 'INFLIGHT', 'SENT')),
    created_offline  INTEGER NOT NULL DEFAULT 0,
    attempts         INTEGER NOT NULL DEFAULT 0,
    created_at       TEXT    NOT NULL,
    last_attempt_at  TEXT,
    sent_at          TEXT,
    last_error       TEXT
);
CREATE INDEX IF NOT EXISTS idx_outbox_status_id ON outbox_telemetry (status, id);
CREATE INDEX IF NOT EXISTS idx_outbox_sent_at ON outbox_telemetry (sent_at);
`);
global.set("outbox_db", db);
const n = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
node.status({ fill: "green", shape: "dot", text: "outbox aberta · pendentes " + n });

finalize:
const db = global.get("outbox_db");
if (db) { try { db.close(); } catch (e) { /* já fechado */ } }
global.set("outbox_db", undefined);

func:
// =============================================================================
// OUTBOX — despachante (envio garantido, "pelo menos uma vez", em ordem)
//  1. Só envia com o MQTT conectado.
//  2. INFLIGHT sem PUBACK há mais de ACK_TIMEOUT_MS volta para PENDING (reenvio).
//  3. Enquanto houver INFLIGHT, não manda lote novo -> ordem preservada.
//  4. Lote de até OUTBOX_BATCH linhas: PENDING -> INFLIGHT e sai para o "mqtt out".
// Mensagem que esperou na outbox sai com buffered=true. Duplicata de reenvio é
// descartada pelo iot-service (msg_id).
// Entradas: tick (__tick__), status do mqtt out, __force_offline__/__force_online__
// =============================================================================
const db = global.get("outbox_db");
if (!db) { return null; }
const ACK_MS = Number(env.get("ACK_TIMEOUT_MS") || 5000);
const BATCH  = Number(env.get("OUTBOX_BATCH") || 100);

function isOnline() { return flow.get("mqtt_online") === true && flow.get("force_offline") !== true; }
function count(st) { return db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status = ?").get(st).n; }
function show() {
    const p = count("PENDING"), f = count("INFLIGHT");
    node.status(isOnline()
        ? { fill: p + f ? "yellow" : "green", shape: "dot", text: "online · pendentes " + p + " · aguardando PUBACK " + f }
        : { fill: "red", shape: "ring", text: "OFFLINE · " + (p + f) + " msg na outbox" });
}

if (msg.status) {
    const was = isOnline();
    flow.set("mqtt_online", msg.status.fill === "green");
    if (!was && isOnline()) node.warn("MQTT reconectado. Na outbox: " + (count("PENDING") + count("INFLIGHT")));
} else if (msg.topic === "__force_offline__") {
    flow.set("force_offline", true);
} else if (msg.topic === "__force_online__") {
    flow.set("force_offline", false);
}
if (!isOnline()) { show(); return null; }

const now = Date.now();
db.prepare(`UPDATE outbox_telemetry SET status = 'PENDING', last_error = 'sem PUBACK'
            WHERE status = 'INFLIGHT' AND last_attempt_at < ?`).run(new Date(now - ACK_MS).toISOString());
if (count("INFLIGHT") > 0) { show(); return null; }

const rows = db.prepare(`SELECT id, topic, payload, created_offline, attempts FROM outbox_telemetry
                         WHERE status = 'PENDING' ORDER BY id LIMIT ?`).all(BATCH);
if (rows.length === 0) { show(); return null; }

const iso = new Date(now).toISOString();
const mark = db.prepare(`UPDATE outbox_telemetry SET status = 'INFLIGHT', attempts = attempts + 1,
                         last_attempt_at = ? WHERE id = ?`);
db.exec("BEGIN");
try { rows.forEach(r => mark.run(iso, r.id)); db.exec("COMMIT"); }
catch (e) { db.exec("ROLLBACK"); throw e; }

const out = rows.map(r => {
    const p = JSON.parse(r.payload);
    if (r.created_offline === 1 || r.attempts > 0) p.buffered = true;
    return { topic: r.topic, payload: p, qos: 1, retain: false, outbox_id: r.id };
});
show();
return [out];

// PUBACK recebido (nó "complete" observando o "mqtt out"): a linha vira SENT.
const db = global.get("outbox_db");
if (!db || msg.outbox_id === undefined) { return null; }
db.prepare("UPDATE outbox_telemetry SET status = 'SENT', sent_at = ?, last_error = NULL WHERE id = ?")
  .run(new Date().toISOString(), msg.outbox_id);
const n = (context.get("n") || 0) + 1;
context.set("n", n);
node.status({ fill: "green", shape: "dot", text: "confirmadas (PUBACK): " + n });
return null;

// Erro no publish (nó "catch" do "mqtt out"): volta para PENDING para reenviar.
const db = global.get("outbox_db");
if (!db || msg.outbox_id === undefined) { return null; }
const err = (msg.error && msg.error.message) || "erro no publish";
db.prepare("UPDATE outbox_telemetry SET status = 'PENDING', last_error = ? WHERE id = ? AND status = 'INFLIGHT'")
  .run(String(err).slice(0, 200), msg.outbox_id);
node.status({ fill: "red", shape: "ring", text: err });
return null;

// Apaga o que já foi confirmado há mais de OUTBOX_RETENTION_H horas (padrão 24 h).
const db = global.get("outbox_db");
if (!db) { return null; }
const hours = Number(env.get("OUTBOX_RETENTION_H") || 24);
const limit = new Date(Date.now() - hours * 3600 * 1000).toISOString();
const r = db.prepare("DELETE FROM outbox_telemetry WHERE status = 'SENT' AND sent_at < ?").run(limit);
node.status({ text: "removidas: " + r.changes + " (" + new Date().toLocaleTimeString() + ")" });
return null;

// GET /edge/status -> diagnóstico LOCAL do gateway (usado também pelo replay)
const db = global.get("outbox_db");
const counts = { PENDING: 0, INFLIGHT: 0, SENT: 0 };
if (db) {
    db.prepare("SELECT status, COUNT(*) AS n FROM outbox_telemetry GROUP BY status").all()
      .forEach(r => { counts[r.status] = r.n; });
}
msg.payload = {
    input_mode: env.get("INPUT_MODE") || "SIMULADOR",
    capture: env.get("CAPTURE") === "true",
    mqtt_online: flow.get("mqtt_online") === true,
    forced_offline: flow.get("force_offline") === true,
    outbox_ready: !!db,
    outbox: counts,
    last_telemetry: flow.get("last_telemetry") || null
};
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;

// GET /edge/recent?since_seq=N -> mensagens agregadas recentes (até 3000), em ordem
const since = Number((msg.req && msg.req.query && msg.req.query.since_seq) || 0);
msg.payload = (flow.get("recent") || []).filter(m => m.seq > since);
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;

// Trilho 1: recebe a amostra normalizada (100 ms) do fluxo de ingestão e atualiza o contexto global.
// NÃO publica: quem publica é o "consolidar" (WebSocket local) e a ponte WSS (envelope a cada 500 ms).
const s = msg.payload || {};
const st = s.stations || {};
const emergencia = s.buttons && s.buttons.emergency_pressed === true;
const flags = s.flags || {};
const est = s.estoque || {};

const telemetria = global.get('telemetria') || {
    timestamp: new Date().toISOString(),
    roboUR: { posicaoCartesiana: { x: 0, y: 0, z: 0 }, posicaoJuntas: [0, 0, 0, 0, 0, 0], garraFechada: false },
    esteira: { motorLigado: false, pecaAtual: null },
    estacoes: {
        estoque: { status: 'AGUARDANDO', magazine: 0 }, processo: { status: 'AGUARDANDO', magazine: 0 },
        montagem: { status: 'AGUARDANDO', magazine: 0 }, expedicao: { status: 'AGUARDANDO', magazine: 0 }
    },
    pedidoAtual: null
};

// Status do contrato (enum): EMERGENCIA > OPERANDO > AGUARDANDO.
// "segurancaOK = true" é o estado NORMAL da estação, então não indica operação; usamos esteira/ocupado.
function status(emerg, operando) { return emerg ? 'EMERGENCIA' : (operando ? 'OPERANDO' : 'AGUARDANDO'); }
const rodando = (e) => !!e && (e.esteira1 === true || e.esteira2 === true);

// Estoque: "ocupado" do CLP do Estoque; no Teste B, motorEsteira1 liga a esteira do Estoque.
const estoqueOperando = flags.ocupado === true || (s.source === 'TESTE_B' && s.belt_running === true);
telemetria.estacoes.estoque   = { status: status(emergencia, estoqueOperando),
                                  magazine: typeof est.posicao === 'number' ? est.posicao : 0 };
telemetria.estacoes.processo  = { status: status(emergencia, rodando(st.processo)),  magazine: 0 };
telemetria.estacoes.montagem  = { status: status(emergencia, rodando(st.montagem)),  magazine: 0 };
telemetria.estacoes.expedicao = { status: status(emergencia, rodando(st.expedicao)), magazine: 0 };
telemetria.esteira.motorLigado = s.belt_running === true;
// magazine (exceto posEstoque do Teste B), robô (roboUR) e peça atual não existem no mapa de tags do CLP:
// ficam nos valores padrão até o inventário trazer os endereços.

telemetria.timestamp = new Date().toISOString();
global.set('telemetria', telemetria);

// Sprint 3: dados da janela para o envelope da ponte WSS (quantas leituras e se houve emergência).
const jan = global.get('telemetria_janela') || { n: 0, emerg: false };
jan.n += 1; jan.emerg = jan.emerg || emergencia;
global.set('telemetria_janela', jan);
global.set('telemetria_t', Date.now());
global.set('telemetria_src', s.source || null);
return null;

// Só consulta o Elipse quando ELIPSE_ENABLED=true (evita erro de timeout no simulador).
if (env.get('ELIPSE_ENABLED') !== 'true') { return null; }
msg.url = env.get('ELIPSE_URL') || 'http://192.168.150.200:4321/api/Events/order/current';
return msg;

// Trilho 2: guarda o pedido atual no contexto global para o "consolidar" usar.
const telemetria = global.get('telemetria');
if (!telemetria) return null;
const p = msg.payload;
if (p && p.trackingCode) {
    telemetria.pedidoAtual = { trackingCode: p.trackingCode, componentId: p.componentId, status: p.status || 'EM_PRODUCAO' };
    global.set('telemetria', telemetria);
}
return null;

// Trilho 3: filtra eco, valida ação, origem e token. Saída 1 = comando válido, saída 2 = ack de rejeição.
// Chega pelo WebSocket local (painel/SPA local) ou pela ponte WSS (msg._via = "wss").
if (typeof msg.payload === 'string') { try { msg.payload = JSON.parse(msg.payload); } catch (e) { return null; } }
const c = msg.payload;
if (!c || typeof c !== 'object') { return null; }
if (c.roboUR || c.tipo === 'ack') { return null; }   // eco de telemetria/ack
if (!c.acao) { return null; }

const ACOES = ['START', 'STOP', 'RESET', 'EMERGENCY_STOP'];
const origensPermitidas = ['unidade1-grupo1', 'unidade1-grupo2', 'unidade1-grupo3', 'unidade1-grupo4', 'unidade1-grupo5'];
const canal = msg._via || 'ws-local';
const auditar = global.get('auditar');
const nack = (motivo) => {
    if (typeof auditar === 'function') auditar({ canal: canal, cmd_id: c.id, acao: c.acao, origem: c.origem, aceito: false,
        motivo: motivo, modo: global.get('input_mode_ingestao') || null, destino: 'NENHUM' });
    return { payload: { tipo: 'ack', acao: c.acao, origem: c.origem || null, id: c.id || null,
        aceito: false, motivo: motivo, ts: new Date().toISOString() }, _session: msg._session, _via: msg._via };
};

if (!ACOES.includes(c.acao)) { node.warn('Comando rejeitado (ação desconhecida): ' + c.acao); return [null, nack('ação desconhecida')]; }

// EMERGENCY_STOP é sempre aceito (bypassa a whitelist de origens): a segurança prevalece.
if (c.acao !== 'EMERGENCY_STOP') {
    if (!origensPermitidas.includes(c.origem)) { node.warn('Comando rejeitado de origem: ' + c.origem); return [null, nack('origem não permitida')]; }
    const token = env.get('WS_TOKEN');
    if (token && canal === 'ws-local' && c.token !== token) { node.warn('Token inválido de ' + c.origem); return [null, nack('token inválido')]; }
}
msg.comando = c;
return [msg, null];

// =============================================================================
// Aplica o comando validado.
//   Saída 1 = simulador (link) · Saída 2 = ack para quem enviou · Saída 3 = escrita no CLP (pulso -> s7 out)
//   SIMULADOR -> vai ao simulador.
//   CLP       -> SÓ escreve com autorização escrita do responsável da automação:
//                CLP_WRITE_AUTHORIZED = "true" E CLP_WRITE_AUTH_REF = referência do documento
//                (ex.: docs/evidence/sprint3/G1-S3-autorizacao-escrita-clp.md). Sem isso: BLOQUEADO.
//   REPLAY / TESTE_B -> nada é escrito.
// A emergência física e os intertravamentos do CLP prevalecem sobre qualquer comando de software.
// =============================================================================
const c = msg.comando;
const modo = global.get('input_mode_ingestao') || env.get('INPUT_MODE') || 'SIMULADOR';
const canal = msg._via || 'ws-local';
const auditar = global.get('auditar');
const aud = (ok, motivo, destino, escrita) => typeof auditar === 'function'
    ? auditar({ canal: canal, cmd_id: c.id, acao: c.acao, origem: c.origem, aceito: ok, motivo: motivo, modo: modo,
                destino: destino, escrita_status: escrita || null })
    : null;
const ack = (ok, motivo, destino) => ({ payload: { tipo: 'ack', acao: c.acao, origem: c.origem || null, id: c.id || null,
    aceito: ok, motivo: motivo || null, modo: modo, destino: destino, ts: new Date().toISOString() },
    _session: msg._session, _via: msg._via });

if (modo === 'SIMULADOR') {
    const MAP = { START: 'START', STOP: 'STOP', RESET: 'RESET', EMERGENCY_STOP: 'EMERGENCY' };
    aud(true, 'simulador', 'SIMULADOR');
    return [{ topic: 'sim_cmd', payload: MAP[c.acao] }, ack(true, null, 'SIMULADOR'), null];
}

if (modo === 'CLP') {
    const autorizado = String(env.get('CLP_WRITE_AUTHORIZED') || '').toLowerCase() === 'true';
    const ref = String(env.get('CLP_WRITE_AUTH_REF') || '').trim();
    if (!autorizado || !ref) {
        const m = 'escrita no CLP bloqueada: falta autorização escrita (CLP_WRITE_AUTHORIZED / CLP_WRITE_AUTH_REF)';
        node.warn(m + ' — ' + c.acao + ' de ' + (c.origem || '?'));
        aud(false, m, 'NENHUM');
        return [null, ack(false, m, 'NENHUM'), null];
    }
    const auditId = aud(true, 'autorização ' + ref, 'CLP', 'ENVIADA');
    node.status({ fill: 'yellow', shape: 'dot', text: c.acao + ' -> CLP (' + ref + ')' });
    return [null, ack(true, 'encaminhado ao CLP (autorização ' + ref + ')', 'CLP'),
            { acao: c.acao, origem: c.origem, audit_id: auditId }];
}

const m = 'modo ' + modo + ': nada é escrito';
aud(false, m, 'NENHUM');
return [null, ack(false, m, 'NENHUM'), null];

// Junta o estado global numa mensagem única e publica (broadcast para todos os clientes do /ws).
const telemetria = global.get('telemetria');
if (!telemetria) { return null; }   // ainda sem leitura
telemetria.timestamp = new Date().toISOString();
msg.payload = telemetria;
return msg;

// Ack do comando volta pelo mesmo caminho por onde o comando chegou:
//   ponte WSS (msg._via = "wss") -> saída 2 (link para a aba da ponte) · WebSocket local -> saída 1
if (msg._via === 'wss') { return [null, { topic: '__send_raw__', payload: msg.payload }]; }
return [msg, null];

// =============================================================================
// Pulso no CLP: escreve TRUE no bit do comando e, depois de CLP_PULSE_MS (500 ms),
// escreve FALSE — igual a apertar e soltar o botão. Um nó "s7 out" por ação:
//   saída 1 START          -> DB1,X0.4      saída 3 RESET          -> DB1,X0.6
//   saída 2 STOP           -> DB1,X0.5      saída 4 EMERGENCY_STOP -> DB1,X0.7
// Só recebe mensagens do aplicarComando quando há autorização escrita.
// =============================================================================
const IDX = { START: 0, STOP: 1, RESET: 2, EMERGENCY_STOP: 3 };
const i = IDX[msg.acao];
if (i === undefined) { return null; }
const PULSE = Number(env.get('CLP_PULSE_MS') || 500);
const saida = (v, fase) => { const o = [null, null, null, null];
    o[i] = { payload: v, acao: msg.acao, audit_id: msg.audit_id, fase: fase }; return o; };
setTimeout(() => node.send(saida(false, 'SOLTA')), PULSE);
node.status({ fill: 'blue', shape: 'dot', text: msg.acao + ' (pulso ' + PULSE + ' ms)' });
return saida(true, 'APERTA');

// Escrita confirmada pelo CLP (nó "complete" dos s7 out): registra na auditoria.
const f = global.get('auditar_escrita');
if (msg.fase === 'APERTA' && typeof f === 'function') f(msg.audit_id, 'CONFIRMADA', null);
node.status({ fill: 'green', shape: 'dot', text: msg.acao + ' ' + msg.fase + ' ok' });
return null;

// Erro na escrita no CLP (nó "catch" dos s7 out): registra na auditoria.
const f = global.get('auditar_escrita');
const err = (msg.error && msg.error.message) || 'erro na escrita';
if (typeof f === 'function') f(msg.audit_id, 'ERRO', err);
node.warn('Escrita no CLP falhou (' + (msg.acao || '?') + '): ' + err);
node.status({ fill: 'red', shape: 'ring', text: err });
return null;

// =============================================================================
// PONTE WSS — monta o ENVELOPE do contrato a cada 500 ms (seção 6 do roteiro, passo 3)
//  - Base: estado consolidado pelo nó "montarTelemetria" (aba SPA) com as amostras de 100 ms.
//  - Janela: as ~5 leituras desde o último frame. Se alguma teve emergência, o frame sai
//    com EMERGENCIA (um pulso de 100 ms nunca se perde).
//  - timestamp: momento da consolidação, ISO-8601 UTC.
//  - Sem leitura nova na janela: reaproveita o último valor bom e marca meta.stale = true.
//  - meta: metadados da ponte (proposta ao G5): msg_id e seq para deduplicar e
//    conferir lacunas, buffered = saiu da outbox depois de uma queda.
// =============================================================================
const WINDOW = Number(env.get("ENVELOPE_WINDOW_MS") || 500);
const NODE_ID = env.get("NODE_ID") || "borda_n2";
const now = Date.now();

const tel = global.get("telemetria");
const lastT = global.get("telemetria_t") || 0;
const jan = global.get("telemetria_janela") || { n: 0, emerg: false };
global.set("telemetria_janela", { n: 0, emerg: false });

const base = tel || context.get("lkg");
if (!base) { node.status({ fill: "grey", shape: "ring", text: "aguardando a primeira leitura" }); return null; }
context.set("lkg", JSON.parse(JSON.stringify(base)));

const frame = JSON.parse(JSON.stringify(base));
if (jan.emerg) { for (const k of Object.keys(frame.estacoes || {})) frame.estacoes[k].status = "EMERGENCIA"; }
frame.timestamp = new Date(now).toISOString();

const stale = jan.n === 0 || (now - lastT) > 2 * WINDOW;
const seq = (context.get("seq") || 0) + 1;
context.set("seq", seq);
frame.meta = {
    contrato: "envelope-telemetria-1.0",
    node_id: NODE_ID,
    msg_id: NODE_ID + "-" + now + "-" + seq,
    boot: context.get("boot"),
    seq: seq,
    origem_dados: global.get("telemetria_src") || null,
    amostras: jan.n,
    stale: stale,
    buffered: false
};
msg.payload = frame;
node.status({ fill: stale ? "yellow" : "green", shape: "dot", text: "seq " + seq + " · " + jan.n + " amostras" + (stale ? " · STALE" : "") });
return msg;

initialize:
// Identificador desta execução (muda a cada deploy/reinício): o consumidor usa
// meta.boot para saber que a sequência meta.seq recomeçou.
context.set("boot", new Date().toISOString());
context.set("seq", 0);

func:
// =============================================================================
// PONTE WSS — grava o envelope na outbox ANTES de qualquer envio (store-and-forward).
// Saída -> cliente WSS (pede um despacho imediato, sem esperar o próximo tick).
// =============================================================================
const db = global.get("ponte_db");
if (!db) { node.status({ fill: "red", shape: "ring", text: "outbox fechada" }); node.error("Outbox da ponte indisponível", msg); return null; }
const MAX = Number(env.get("PONTE_OUTBOX_MAX") || 200000);
const p = msg.payload;
const online = flow.get("wss_online") === true;

db.prepare(`INSERT OR IGNORE INTO outbox_telemetry (msg_id, topic, payload, created_offline, created_at)
            VALUES (?, ?, ?, ?, ?)`)
  .run(p.meta.msg_id, "wss:telemetria", JSON.stringify(p), online ? 0 : 1, new Date().toISOString());

const pending = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
if (pending > MAX) {
    const excess = pending - MAX;
    db.prepare(`DELETE FROM outbox_telemetry WHERE id IN
                (SELECT id FROM outbox_telemetry WHERE status = 'PENDING' ORDER BY id LIMIT ?)`).run(excess);
    node.warn("Outbox da ponte cheia (" + MAX + "). Descartados " + excess + " frames mais antigos.");
}
node.status({ fill: online ? "green" : "yellow", shape: "dot", text: (online ? "" : "OFFLINE · ") + "na fila: " + Math.min(pending, MAX) });
return { topic: "__tick__" };

initialize:
// Abre o SQLite da ponte WSS (arquivo separado do MQTT) e cria as tabelas
// (mesmo DDL de db/outbox_telemetry.sql). Requer Node.js >= 22.13 e o settings.js do repositório.
const sqlite = global.get("sqlite");
if (!sqlite) {
    node.status({ fill: "red", shape: "ring", text: "SQLite indisponível (Node.js >= 22.13?)" });
    node.error("node:sqlite indisponível. Use Node.js 22.13+ e o settings.js do repositório.");
    return;
}
const file = global.get("pontePath") || "outbox_ponte_wss.sqlite";
const db = new sqlite.DatabaseSync(file);
db.exec("PRAGMA journal_mode = WAL;");
db.exec(`CREATE TABLE IF NOT EXISTS outbox_telemetry (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    msg_id           TEXT    NOT NULL UNIQUE,
    topic            TEXT    NOT NULL,
    payload          TEXT    NOT NULL,
    status           TEXT    NOT NULL DEFAULT 'PENDING'
                     CHECK (status IN ('PENDING', 'INFLIGHT', 'SENT')),
    sent             INTEGER GENERATED ALWAYS AS (CASE WHEN status = 'SENT' THEN 1 ELSE 0 END) VIRTUAL,
    created_offline  INTEGER NOT NULL DEFAULT 0,
    attempts         INTEGER NOT NULL DEFAULT 0,
    created_at       TEXT    NOT NULL,
    last_attempt_at  TEXT,
    sent_at          TEXT,
    last_error       TEXT
);
CREATE INDEX IF NOT EXISTS idx_outbox_status_id ON outbox_telemetry (status, id);
CREATE INDEX IF NOT EXISTS idx_outbox_sent_at ON outbox_telemetry (sent_at);
CREATE TABLE IF NOT EXISTS audit_comandos (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    ts              TEXT    NOT NULL,
    canal           TEXT    NOT NULL,
    cmd_id          TEXT,
    acao            TEXT,
    origem          TEXT,
    decisao         TEXT    NOT NULL CHECK (decisao IN ('ACEITO', 'REJEITADO')),
    motivo          TEXT,
    modo            TEXT,
    destino         TEXT,
    escrita_status  TEXT    CHECK (escrita_status IS NULL OR escrita_status IN ('ENVIADA', 'CONFIRMADA', 'ERRO')),
    escrita_erro    TEXT
);
CREATE INDEX IF NOT EXISTS idx_audit_ts ON audit_comandos (ts);
`);
// Reinício do Node-RED: o que estava aguardando confirmação volta para a fila (reenvio em ordem).
db.exec("UPDATE outbox_telemetry SET status = 'PENDING', last_error = 'reinicio do Node-RED' WHERE status = 'INFLIGHT';");
global.set("ponte_db", db);

// Auditoria do canal de comandos (usada por validarComando / aplicarComando / escrita no CLP).
const ins = db.prepare(`INSERT INTO audit_comandos (ts, canal, cmd_id, acao, origem, decisao, motivo, modo, destino, escrita_status)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`);
const upd = db.prepare("UPDATE audit_comandos SET escrita_status = ?, escrita_erro = ? WHERE id = ?");
global.set("auditar", function (r) {
    try {
        const s = (v) => (v === undefined || v === null) ? null : String(v).slice(0, 200);
        const res = ins.run(new Date().toISOString(), s(r.canal) || "ws-local", s(r.cmd_id), s(r.acao), s(r.origem),
            r.aceito ? "ACEITO" : "REJEITADO", s(r.motivo), s(r.modo), s(r.destino), r.escrita_status || null);
        return Number(res.lastInsertRowid);
    } catch (e) { node.warn("auditoria falhou: " + e.message); return null; }
});
global.set("auditar_escrita", function (id, status, erro) {
    try { if (id) upd.run(status, erro ? String(erro).slice(0, 200) : null, id); } catch (e) { node.warn("auditoria falhou: " + e.message); }
});
const n = db.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status != 'SENT'").get().n;
node.status({ fill: "green", shape: "dot", text: "outbox da ponte aberta · pendentes " + n });

