const st = context.get("st");
if (!st || !st.api) { return null; }
if (msg.topic === "__send_raw__") { st.api.sendRaw(msg.payload); return null; }
if (msg.topic === "__force_offline__") { st.api.forceOffline(); return null; }
if (msg.topic === "__force_online__") { st.api.forceOnline(); return null; }
st.api.tick();
return null;

initialize:
// =============================================================================
// PONTE WSS — cliente WebSocket seguro + despachante da outbox (um nó só, porque o
// mesmo socket envia a telemetria, recebe os comandos e confirma a entrega).
//  - URL: variável de ambiente do SISTEMA SMART40_BROKER_URL (wss://smart40-broker.onrender.com)
//         e token em SMART40_AGENT_TOKEN. Nada disso fica no flows.json.
//  - Recusa ws://, URL da Vercel e token dentro da URL (settings.js também barra).
//  - Reconexão a cada WSS_RECONNECT_MS (5000 ms). Código 4001 = token recusado.
//  - Envio "pelo menos uma vez" (equivalente ao QoS 1): a linha fica INFLIGHT e só
//    vira SENT depois de WSS_ACK_GRACE_MS com a MESMA conexão aberta e o buffer de
//    saída vazio (WSS_CONFIRM=GRACE), ou quando o broker devolve o frame (WSS_CONFIRM=ECHO).
//    Se a conexão cair, tudo que estava INFLIGHT volta para PENDING e é reenviado
//    em ordem (o consumidor descarta duplicatas por meta.msg_id).
// Entradas: __tick__ · __send_raw__ (ack de comando) · __force_offline__ / __force_online__
// Saída 1: mensagens recebidas do broker (comandos) · Saída 2: eventos de conexão
// =============================================================================
const WS = global.get("WebSocket");
const RECONNECT_MS = Number(env.get("WSS_RECONNECT_MS") || 5000);
const GRACE_MS = Number(env.get("WSS_ACK_GRACE_MS") || 1000);
const ACK_TIMEOUT_MS = Number(env.get("WSS_ACK_TIMEOUT_MS") || 5000);
const BATCH = Number(env.get("WSS_BATCH") || 50);
const MODE = String(env.get("WSS_CONFIRM") || "GRACE").toUpperCase();
const base = String(env.get("SMART40_BROKER_URL") || "").trim();
const token = String(env.get("SMART40_AGENT_TOKEN") || "").trim();

const st = { ws: null, online: false, epoch: 0, timer: null, closing: false, forced: false,
             lastClose: null, connects: 0, sent: 0, confirmed: 0, requeued: 0, erroConfig: null };
context.set("st", st);
flow.set("wss_online", false);

function erroUrl(u) {
    if (!u) return "SMART40_BROKER_URL não definida (variável de ambiente do sistema)";
    if (!/^wss:\/\//i.test(u)) return "SMART40_BROKER_URL deve começar com wss:// (ws:// é proibido)";
    if (/vercel\.(app|com)/i.test(u)) return "a ponte nunca aponta para a Vercel";
    if (/[?&]token=/i.test(u)) return "o token vai em SMART40_AGENT_TOKEN, não dentro da URL";
    if (!token) return "SMART40_AGENT_TOKEN não definida (variável de ambiente do sistema)";
    return null;
}
function host() { try { return new URL(base).host; } catch (e) { return "?"; } }
function db() { return global.get("ponte_db"); }
function count(s) { const d = db(); return d ? d.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status = ?").get(s).n : 0; }
function show() {
    if (st.erroConfig) { node.status({ fill: "red", shape: "ring", text: st.erroConfig }); return; }
    const p = count("PENDING"), f = count("INFLIGHT");
    if (st.online) node.status({ fill: p + f > 2 ? "yellow" : "green", shape: "dot", text: "wss " + host() + " · fila " + p + " · aguardando " + f });
    else node.status({ fill: "red", shape: "ring", text: (st.forced ? "LINK DERRUBADO (teste)" : "OFFLINE") + " · " + (p + f) + " na outbox" +
        (st.lastClose && st.lastClose.code === 4001 ? " · TOKEN RECUSADO (4001)" : "") });
}
function evento(tipo, extra) {
    node.send([null, { topic: "conexao", payload: Object.assign({ evento: tipo, epoch: st.epoch, ts: new Date().toISOString() }, extra || {}) }]);
}
function requeue(motivo) {
    const d = db(); if (!d) return 0;
    const r = d.prepare("UPDATE outbox_telemetry SET status = 'PENDING', last_error = ? WHERE status = 'INFLIGHT'").run(motivo);
    st.requeued += r.changes;
    return r.changes;
}
function setOnline(v) { st.online = v; flow.set("wss_online", v); }
// Uma tentativa de conexão a cada RECONNECT_MS: contado a partir da queda (se chegou a conectar)
// ou do início da tentativa anterior (se nem conectou), para não somar o tempo de timeout.
function schedule(desde) {
    if (st.closing || st.forced || st.timer || st.erroConfig) return;
    const espera = Math.max(0, RECONNECT_MS - (Date.now() - (desde || Date.now())));
    st.timer = setTimeout(connect, espera);
}
function connect() {
    st.timer = null;
    if (st.closing || st.forced || st.ws) return;
    if (!WS) { st.erroConfig = "WebSocket indisponível (Node.js >= 22 e settings.js)"; show(); node.error(st.erroConfig); return; }
    let sock;
    const inicio = Date.now(); let abriu = false;
    try { sock = new WS(base + (base.indexOf("?") >= 0 ? "&" : "?") + "token=" + encodeURIComponent(token)); }
    catch (e) { node.error("Falha ao abrir " + host() + ": " + e.message); schedule(inicio); return; }
    st.ws = sock;
    sock.onopen = function () {
        if (st.ws !== sock) return;
        abriu = true; st.epoch += 1; st.connects += 1; setOnline(true);
        const n = requeue("reconexao");
        evento("conectado", { host: host(), reenfileirados: n });
        if (st.connects > 1) node.warn("Ponte WSS reconectada a " + host() + ". Na outbox: " + (count("PENDING") + count("INFLIGHT")));
        show();
        tick();
    };
    sock.onmessage = function (ev) {
        let txt = ev.data;
        if (typeof txt !== "string") { try { txt = Buffer.from(txt).toString("utf8"); } catch (e) { return; } }
        let data;
        try { data = JSON.parse(txt); } catch (e) { return; }
        // Eco do próprio frame (WSS_CONFIRM=ECHO): confirma a entrega daquele msg_id.
        if (data && data.meta && data.meta.msg_id && data.meta.node_id === (env.get("NODE_ID") || "borda_n2")) {
            if (MODE === "ECHO") {
                const d = db();
                if (d) { const r = d.prepare("UPDATE outbox_telemetry SET status = 'SENT', sent_at = ?, last_error = NULL WHERE msg_id = ? AND status = 'INFLIGHT'")
                    .run(new Date().toISOString(), data.meta.msg_id); st.confirmed += r.changes; }
            }
            return;
        }
        node.send([{ payload: data, _via: "wss" }, null]);
    };
    let terminou = false;
    function terminar(code, reason) {
        if (terminou) return;
        terminou = true;
        if (st.ws !== sock) return;
        st.ws = null; setOnline(false);
        st.lastClose = { code: code, reason: reason || "", ts: new Date().toISOString() };
        const n = requeue("conexao caiu (" + code + ")");
        if (code === 4001) node.warn("Broker recusou o token do agente (código 4001). Solicite novo token ao G5.");
        evento("desconectado", { code: code, reason: reason || "", reenfileirados: n });
        show();
        schedule(abriu ? Date.now() : inicio);
    }
    sock.onclose = function (ev) { terminar(ev.code, ev.reason); };
    // No Node.js 22, conexão recusada (broker fora, sem rede) dispara só "error", sem "close".
    // Se o "close" não vier logo em seguida, tratamos como queda (1006) e agendamos a reconexão.
    sock.onerror = function () { setTimeout(function () { terminar(1006, "erro de rede"); }, 300); };
}
function markSent(ids) {
    const d = db(); if (!d || !ids.length) return;
    const up = d.prepare("UPDATE outbox_telemetry SET status = 'SENT', sent_at = ?, last_error = NULL WHERE id = ? AND status = 'INFLIGHT'");
    const iso = new Date().toISOString();
    d.exec("BEGIN");
    try { ids.forEach(id => { st.confirmed += up.run(iso, id).changes; }); d.exec("COMMIT"); } catch (e) { d.exec("ROLLBACK"); throw e; }
}
function tick() {
    const d = db();
    if (!d || !st.online || !st.ws || st.ws.readyState !== 1) { show(); return; }
    const now = Date.now();
    // 1) Confirmação
    if (MODE === "ECHO") {
        const old = d.prepare("SELECT COUNT(*) AS n FROM outbox_telemetry WHERE status = 'INFLIGHT' AND last_attempt_at < ?")
                     .get(new Date(now - ACK_TIMEOUT_MS).toISOString()).n;
        if (old > 0) requeue("sem eco do broker");      // reenvia TUDO a partir do mais antigo: ordem mantida
    } else if (st.ws.bufferedAmount === 0) {
        const ids = d.prepare("SELECT id FROM outbox_telemetry WHERE status = 'INFLIGHT' AND last_attempt_at <= ? ORDER BY id")
                     .all(new Date(now - GRACE_MS).toISOString()).map(r => r.id);
        markSent(ids);
    }
    // 2) Envio em ordem (id crescente)
    const rows = d.prepare("SELECT id, payload, created_offline, attempts FROM outbox_telemetry WHERE status = 'PENDING' ORDER BY id LIMIT ?").all(BATCH);
    if (rows.length) {
        const iso = new Date(now).toISOString();
        const mark = d.prepare("UPDATE outbox_telemetry SET status = 'INFLIGHT', attempts = attempts + 1, last_attempt_at = ? WHERE id = ?");
        for (const r of rows) {
            const p = JSON.parse(r.payload);
            if (r.created_offline === 1 || r.attempts > 0) { p.meta.buffered = true; }
            if (r.attempts > 0) { p.meta.reenvio = r.attempts; }
            try { st.ws.send(JSON.stringify(p)); }
            catch (e) { node.warn("envio falhou: " + e.message); break; }
            mark.run(iso, r.id);
            st.sent += 1;
        }
    }
    show();
}
function sendRaw(obj) {
    if (st.online && st.ws && st.ws.readyState === 1) { st.ws.send(JSON.stringify(obj)); return true; }
    node.warn("ack não enviado (ponte offline): " + JSON.stringify(obj).slice(0, 120));
    return false;
}
function forceOffline() {
    st.forced = true;
    if (st.timer) { clearTimeout(st.timer); st.timer = null; }
    if (st.ws) { try { st.ws.close(4000, "teste de resiliencia"); } catch (e) {} }
    evento("link_derrubado_teste");
    show();
}
function forceOnline() { st.forced = false; evento("link_restaurado_teste"); connect(); }
function info() {
    return { online: st.online, host: host(), epoch: st.epoch, conexoes: st.connects, ultimo_fechamento: st.lastClose,
             link_derrubado_teste: st.forced, enviados: st.sent, confirmados: st.confirmed, reenfileirados: st.requeued,
             modo_confirmacao: MODE, reconexao_ms: RECONNECT_MS, erro_config: st.erroConfig };
}
st.api = { tick, sendRaw, forceOffline, forceOnline, info, show };
flow.set("wss_info", info);

st.erroConfig = erroUrl(base);
if (st.erroConfig) { node.error("Ponte WSS desativada: " + st.erroConfig); show(); }
else { connect(); }

finalize:
const st = context.get("st");
if (st) {
    st.closing = true;
    if (st.timer) { clearTimeout(st.timer); st.timer = null; }
    if (st.ws) { try { st.ws.close(1000, "redeploy"); } catch (e) {} st.ws = null; }
}
flow.set("wss_online", false);

func:
// Mensagens que chegam do broker: comando (tem "acao") vai para o validarComando
// (aba SPA); o resto (telemetria de outros nós, avisos do broker) só aparece no debug.
const p = msg.payload;
if (p && typeof p === "object" && typeof p.acao === "string") {
    return [{ payload: p, _via: "wss" }, null];
}
return [null, msg];

// Apaga da outbox da ponte o que já foi confirmado há mais de OUTBOX_RETENTION_H horas (padrão 24 h).
const db = global.get("ponte_db");
if (!db) { return null; }
const hours = Number(env.get("OUTBOX_RETENTION_H") || 24);
const limit = new Date(Date.now() - hours * 3600 * 1000).toISOString();
const r = db.prepare("DELETE FROM outbox_telemetry WHERE status = 'SENT' AND sent_at < ?").run(limit);
node.status({ text: "removidos: " + r.changes + " (" + new Date().toLocaleTimeString() + ")" });
return null;

// GET /edge/ponte -> diagnóstico local da ponte WSS (nunca mostra o token)
const db = global.get("ponte_db");
const counts = { PENDING: 0, INFLIGHT: 0, SENT: 0 };
if (db) {
    db.prepare("SELECT status, COUNT(*) AS n FROM outbox_telemetry GROUP BY status").all().forEach(r => { counts[r.status] = r.n; });
}
const info = flow.get("wss_info");
msg.payload = {
    input_mode: global.get("input_mode_ingestao") || null,
    ponte: typeof info === "function" ? info() : null,
    outbox: counts,
    outbox_pronta: !!db
};
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;

// GET /edge/comandos?limit=50 -> últimos comandos recebidos (auditoria)
const db = global.get("ponte_db");
const lim = Math.min(Number((msg.req && msg.req.query && msg.req.query.limit) || 50), 500);
msg.payload = db ? db.prepare("SELECT * FROM audit_comandos ORDER BY id DESC LIMIT ?").all(lim) : [];
msg.headers = { "Content-Type": "application/json" };
msg.statusCode = 200;
return msg;
